<template><main class="activity-page"><NavBar/><AdSlot class="page-banner" placement="banner"/><div class="activity-workspace"><aside class="page-ad-rail"><AdSlot placement="sidebar"/><AdSlot placement="sidebar"/><AdSlot placement="sidebar"/></aside><section class="activity-main"><header class="page-head"><div><span class="eyebrow">What happened</span><h1>Activity</h1></div><button @click="readAll">Mark all read</button></header><nav class="filters" aria-label="Filter activity"><button v-for="option in filters" :key="option.value" :class="{active:filter===option.value}" :aria-pressed="filter===option.value" @click="filter=option.value">{{ option.label }}</button></nav><section v-for="group in grouped" :key="group.label" class="day-group"><h2>{{ group.label }}</h2><article v-for="item in group.items" :key="item.id" :class="{unread:!item.read,clickable:item.post_id||item.actor_id}" role="link" tabindex="0" @click="open(item)" @keydown.enter="open(item)" @keydown.space.prevent="open(item)"><button class="actor-link" type="button" :disabled="!item.actor_id" :aria-label="item.actor_name?`View ${item.actor_name} profile`:'Profile unavailable'" @click.stop="item.actor_id&&router.push(`/user/${item.actor_id}`)"><img :src="item.actor_image||'/Default_pfp.svg'" :alt="item.actor_name?`${item.actor_name} profile picture`:'Blugbug user profile picture'"/></button><span class="activity-icon" aria-hidden="true">{{ icon(item.type) }}</span><div><p>{{ item.message }}</p><small>{{ time(item.created_at) }}</small></div><b v-if="!item.read" aria-hidden="true"></b><span v-if="!item.read" class="sr-only">Unread</span></article></section><p v-if="!grouped.length" class="empty">No activity here yet.</p></section><aside class="activity-rail"><section><h3>Activity controls</h3><button @click="filter='comment'">Comments and replies</button><button @click="filter='like'">Likes</button><button @click="filter='share'">Shares</button><button @click="filter='new_post'">New blugs</button></section><AdSlot placement="sidebar"/></aside></div></main></template>
<script setup lang="ts">
import{computed,onMounted,ref}from'vue';import{useRouter}from'vue-router';import NavBar from'./NavBar.vue';import AdSlot from'./AdSlot.vue';import{listNotifications,markAllNotificationsRead,markNotificationRead,type LocalNotification}from'../api/notifications';
const items=ref<LocalNotification[]>([]),router=useRouter(),filter=ref('all');const filters=[{label:'All',value:'all'},{label:'Comments',value:'comment'},{label:'Reactions',value:'like'},{label:'New blugs',value:'new_post'}];
const load=async()=>items.value=(await listNotifications()).notifications;const dayLabel=(date:string)=>{const value=new Date(date),today=new Date(),yesterday=new Date();yesterday.setDate(today.getDate()-1);const key=(d:Date)=>d.toDateString();return key(value)===key(today)?'Today':key(value)===key(yesterday)?'Yesterday':value.toLocaleDateString(undefined,{weekday:'long',month:'short',day:'numeric'});};
const grouped=computed(()=>{const visible=items.value.filter(item=>filter.value==='all'||item.type===filter.value||(filter.value==='comment'&&item.type==='reply'));const map=new Map<string,LocalNotification[]>();visible.forEach(item=>{const label=dayLabel(item.created_at);map.set(label,[...(map.get(label)||[]),item]);});return[...map].map(([label,groupItems])=>({label,items:groupItems}));});
const icon=(type:string)=>({like:'♥',share:'↗',comment:'◯',reply:'↩',follow:'+',bookmark:'◆',new_post:'▤'}[type]||'•');const time=(date:string)=>new Date(date).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'});const readAll=async()=>{await markAllNotificationsRead();await load();};const open=async(item:LocalNotification)=>{if(!item.read)await markNotificationRead(item.id);if(item.post_id)await router.push({name:'SharedBlug',params:{blogId:item.post_id}});else if(item.actor_id)await router.push(`/user/${item.actor_id}`);else await load();};onMounted(load);
</script>
<style scoped>.activity-page{min-height:100vh;padding:112px 22px 90px}.activity-workspace{display:grid;grid-template-columns:minmax(0,1fr) 290px;width:min(1080px,100%);margin:auto;border:1px solid rgba(255,255,255,.16);border-radius:28px;background:rgba(79,71,74,.62);backdrop-filter:blur(24px);overflow:hidden}.activity-main{padding:28px 30px 40px;border-right:1px solid rgba(255,255,255,.14)}.page-head{display:flex;align-items:end;justify-content:space-between}.page-head h1{margin:6px 0 0;font:700 clamp(2.2rem,5vw,3.4rem)/1 Georgia}.page-head>button{padding:8px 11px;border:0;border-radius:9px;background:rgba(239,225,216,.15);color:#fff;font-size:.7rem}.filters{display:flex;gap:22px;margin-top:26px;border-bottom:1px solid var(--line)}.filters button{padding:0 1px 12px;border:0;background:none;color:var(--muted);cursor:pointer}.filters .active{border-bottom:2px solid var(--orange);color:#fff}.day-group h2{margin:24px 0 8px;color:var(--muted);font-size:.72rem;text-transform:uppercase;letter-spacing:.12em}.day-group article{position:relative;display:grid;grid-template-columns:46px 24px 1fr auto;align-items:center;gap:10px;padding:14px 4px;border-bottom:1px solid rgba(255,255,255,.11)}.day-group article.clickable{cursor:pointer}.day-group article>img{width:46px;height:46px;border-radius:50%;object-fit:cover}.activity-icon{display:grid;place-items:center;width:24px;height:24px;border-radius:8px;background:rgba(107,80,246,.18);color:#a99aff}.day-group p{margin:0 0 5px;font-size:.83rem}.day-group small{color:var(--muted);font-size:.67rem}.day-group article>b{width:7px;height:7px;border-radius:50%;background:var(--orange)}.unread{background:rgba(107,80,246,.05)}.activity-rail{display:grid;align-content:start;gap:24px;padding:28px 20px}.activity-rail h3{margin:0 0 12px;font-size:.8rem}.activity-rail section button{display:block;width:100%;padding:10px 0;border:0;border-top:1px solid var(--line);background:none;color:var(--muted);text-align:left;cursor:pointer}.empty{padding:60px;text-align:center;color:var(--muted)}@media(max-width:800px){.activity-page{padding:86px 0 80px}.activity-workspace{display:block;border-left:0;border-right:0;border-radius:0}.activity-main{padding:24px 15px;border:0}.activity-rail{display:none}.day-group article{grid-template-columns:40px 22px 1fr}.day-group article>img{width:40px;height:40px}.day-group article>b{position:absolute;right:5px}.filters{overflow-x:auto}}</style>
